  // 2. return overflow
  let {
  text, length,
  height, x, y, rect
  } = paragraph

  let LINE_HEIGHT = 28 
  let cur_y = y

  while (text.length > 0 && cur_y < y+height) {
    text = draw_line(p,text, 10, cur_y, length)
    cur_y+=LINE_HEIGHT
  }

  if (rect){
    p.noFill()
    p.stroke("white")
    p.rect(x, y, length, height)
    p.noStroke()
  }
}

